/**
 * Web leg of the cross-surface PAPER-COMPONENT golden-parity spine.
 *
 * `fixtures/<type>.golden.json` is generated by
 * `mix barkpark.paper_components.gen_golden_parity` and mirrored byte-for-byte
 * into the api + internal/pdrender trees. Each fixture carries the authored
 * `input` block plus an `expected` STRUCTURAL PROJECTION (node roles / column
 * labels / row titles / glyph-role / nesting). This suite proves the web reader
 * REALIZES that projection — the web half of the shared contract. The web render
 * path is the canonical `@barkpark/react` `renderPortableDocument` (the old web
 * fork `portable-doc.tsx` and its orphaned model `task-board-columns.ts` are
 * both deleted), so the task-board leg asserts the CANONICAL RENDER — label,
 * count, ordered card titles, glyph — directly against the golden projection.
 *
 * The web reader has no RTL/testing-library; the S2 projector legs assert the
 * pure MODEL (`component-projections.ts`) and the render legs assert the
 * canonical HTML string emitter — still no browser and no DOM library.
 *
 * SCOPE (S1): task-board only. status-legend has NO web reader case yet — it is
 * the FIRST S2 item (see the skipped placeholder below); the harness is proven on
 * task-board for web.
 *
 * COVERAGE (honest scope — subset-parity, projection ⊆ native): for every column
 * PRESENT in the projection, all three surfaces agree on label + count + ordered
 * card titles + glyph-role (the task-board leg asserts the canonical RENDER at
 * exact equality). NOT
 * COVERED, FILED not fixed: (a) task-board `open`-task DROP — the Elixir 4-column
 * omit-empty view drops `open` tasks this 5-column web view keeps; a ⊆-projection
 * cannot catch an omission, so the fixture input omits `open`; owned by
 * bug-taskboard-drops-open-tasks (which carries the open-inclusive test that
 * catches the real bug). COVERED since au-w5-status-prose-parity: the status LABEL
 * prose is ONE manifest source; the legend projection asserts the canonical label
 * TEXT ("in progress"/"cancelled") and the web RENDER realizes it (the
 * status-legend RENDER leg below asserts `>${label}</dt>`); board LABELS are
 * asserted against the canonical render, which derives them from the ONE
 * manifest ladder (`@barkpark/react` STATUS_ROLES) — web keeps no hand copy.
 * Legend MEANING is not rendered by the web reader (name-only web parity, a
 * SUPERSET the Elixir/TUI legends carry). The harness never implies parity it does
 * not hold.
 *
 * Run: `node --test __tests__/component-golden-parity.test.ts` (or `pnpm test`).
 */

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";

interface BoardProjection {
  container_role: string;
  columns: Array<{
    role: string;
    label: string;
    glyph_role: string;
    count: number;
    cards: Array<{ title: string }>;
  }>;
}

interface ComponentGolden {
  type: string;
  input: { type: string; snapshot?: Array<Record<string, unknown>> };
  expected: BoardProjection;
}

const fixture: ComponentGolden = JSON.parse(
  readFileSync(
    new URL("./fixtures/task-board.golden.json", import.meta.url),
    "utf8",
  ),
);

/* ── floors — fail LOUD before any leg can go vacuous ── */

function floor(cond: boolean, msg: string): void {
  if (!cond) throw new Error(`component-golden floor violated: ${msg}`);
}

floor(fixture.type === "task-board", `fixture type is ${fixture.type}`);
floor(fixture.expected.container_role === "board", "container_role is not board");
floor(
  fixture.expected.columns.length >= 3,
  `projection has ${fixture.expected.columns.length} columns, need >= 3`,
);
floor(Array.isArray(fixture.input.snapshot), "input.snapshot missing");

/* ══ S2: the task-tracking / composition component family ══════════════════════
 *
 * Each type's web PROJECTOR (`web/lib/component-projections.ts`, which
 * the deleted portable-doc.tsx fork once rendered FROM) must produce the SAME structural projection the
 * Elixir generator committed. deepEqual against the golden `expected` — EXACT,
 * never substring — so a web divergence from the shared truth reds here (matching
 * the task-board leg's exactness). status-legend leads (the S1 skip, now green);
 * the recursive containers (columns / terminal) come last. */

import {
  statusLegendProjection,
  notesProjection,
  noteProjection,
  cardsProjection,
  cardProjection,
  pipelineProjection,
  stageProjection,
  taskDetailProjection,
  roadmapProjection,
  columnsProjection,
  terminalProjection,
  sectionProjection,
  type LegendProjection,
  type NotesProjection,
  type NoteProjection,
  type CardsProjection,
  type CardProjection,
  type PipelineProjection,
  type StageProjection,
  type TaskDetailProjection,
  type RoadmapProjection,
  type ColumnsProjection,
  type TerminalProjection,
  type SectionProjection,
} from "../lib/component-projections.ts";

/** Load a `<type>.golden.json` fixture (input + expected projection). */
function loadFixture(type: string): { input: Record<string, unknown>; expected: unknown } {
  return JSON.parse(
    readFileSync(new URL(`./fixtures/${type}.golden.json`, import.meta.url), "utf8"),
  );
}

/** Every S2 type: its web projector must realize the committed golden projection
 * EXACTLY. `input` is ignored by status-legend (static ladder), read by the rest. */
const S2_CASES: Array<{
  type: string;
  project: (input: Record<string, unknown>) => unknown;
}> = [
  { type: "status-legend", project: () => statusLegendProjection() },
  { type: "notes", project: notesProjection },
  { type: "note", project: noteProjection },
  { type: "cards", project: cardsProjection },
  { type: "card", project: cardProjection },
  { type: "pipeline", project: pipelineProjection },
  { type: "stage", project: stageProjection },
  { type: "task-detail", project: taskDetailProjection },
  { type: "roadmap", project: roadmapProjection },
  // recursive containers last — their projection expresses child NESTING.
  { type: "columns", project: columnsProjection },
  { type: "terminal", project: terminalProjection },
  // section (cd-12): the projector leg C1 ONLY — the deepEqual proof that the web
  // projector realizes the golden layout projection (mode · tracks · gap ·
  // authored-echo cells). The web RENDER leg (now the canonical @barkpark/react
  // renderer — the portable-doc.tsx fork is deleted) is cd-12b — filed, not
  // built here; NO section render-assert is added below.
  { type: "section", project: sectionProjection },
];

for (const { type, project } of S2_CASES) {
  test(`web ${type} projector realizes the golden projection (exact)`, () => {
    const fx = loadFixture(type);
    assert.deepEqual(project(fx.input), fx.expected);
  });
}

/* ══ S2 (LOAD-BEARING): the REAL RENDER realizes the projection ═══════════════
 *
 * The deepEqual loop above proves projector == golden — a valid SECOND layer.
 * THIS layer is the load-bearing one: it drives the ACTUAL canonical reader
 * render (`renderPortableDocument([block])` from `@barkpark/react`) to its `bp-*`
 * HTML string, then asserts the shared projection's fields (container role,
 * labels, card titles, glyph-role, container NESTING) appear in that rendered DOM.
 * A render regression — a dropped field, a mis-wired projector→DOM, a container
 * that re-derives its own structure (columns/terminal never import the projector)
 * — reds HERE even while the projector still matches the golden. Proven non-
 * vacuous: three render tampers (status-legend role, card title-drop, columns
 * nesting) each red this suite; each passed green under the projector-only leg.
 *
 * The render is the CANONICAL `@barkpark/react` surface now (W5 fork-retirement):
 * `renderPortableDocument([block])` emits the same `bp-*` article markup the
 * Phoenix reader and Go TUI produce, so the assertions below key off the `bp-*`
 * DOM (container class + the projection's label/title/text/glyph fields), NOT the
 * retired web fork's Tailwind classes. Pure string emitter — no browser, no JSX
 * transpile, no loader. Every one of the 12 component cases runs for real. */

import { renderPortableDocument, type Block } from "@barkpark/react";

function renderHtml(input: Record<string, unknown>): string {
  return renderPortableDocument([input as Block]);
}

function present(html: string, needle: string, label: string): void {
  assert.ok(
    html.includes(needle),
    `${label}: rendered DOM is missing ${JSON.stringify(needle)}`,
  );
}

/** Leaf text of an authored child block (paragraph content / scalar) — used to
 * assert that a container (columns / terminal) actually NESTS its children's
 * rendered content, catching a dropped or mis-nested child. */
function leafText(node: unknown): string {
  if (!node || typeof node !== "object") return "";
  const n = node as { content?: unknown; value?: unknown; text?: unknown };
  if (Array.isArray(n.content)) return n.content.map(leafText).join("");
  if (typeof n.value === "string") return n.value;
  if (typeof n.text === "string") return n.text;
  return "";
}

/* ── per-type render assertions: the projection's fields MUST appear in the
 * rendered DOM. Field strings are exact (a rename/drop reds). ── */

test("web status-legend RENDER realizes the legend projection (label + glyph)", () => {
  const html = renderHtml({ type: "status-legend" });
  const exp = loadFixture("status-legend").expected as LegendProjection;
  for (const r of exp.rows) {
    // GRADUATED (au-w5-status-prose-parity): the RENDER realizes the canonical
    // LABEL text (progress→"in progress", cancel→"cancelled"), not the raw role
    // slug — a wrong label render reds this leg (S2 render-assert discipline).
    present(html, `>${r.label}</span>`, `legend label ${r.label}`);
    // The spinner role emits an EMPTY CSS-animated glyph span (aria-labelled),
    // never a braille char; every other role prints its literal glyph.
    if (r.spinner) {
      present(html, `bp-g--${r.role}`, `legend spinner glyph role ${r.role}`);
      present(html, `aria-label="${r.label}"`, `legend spinner aria-label ${r.role}`);
    } else {
      present(html, `>${r.glyph}</span>`, `legend glyph ${r.role}`);
    }
  }
});

