test("web cards RENDER realizes every card (title · text · tone class)", () => {
  const input = loadFixture("cards").input;
  const html = renderHtml(input);
  const exp = loadFixture("cards").expected as CardsProjection;
  for (const c of exp.cards) {
    present(html, `>${c.title}</div>`, `cards title ${c.title}`);
    present(html, `>${c.text}</div>`, `cards text ${c.text}`);
    // Canonical tone rides a `bp-card--<tone>` class (skinned by paper-surface.css),
    // not an inlined Tailwind stripe — a dropped tone loses the class and reds.
    if (c.tone) present(html, `bp-card--${c.tone}`, `cards tone ${c.tone}`);
  }
});

/** The authored render marker for one card slot, DERIVED from the fixture input
 * (never hand-typed): the media image alt attr, the title heading text, the body
 * paragraph plain text, the action label. */
function cardSlotMarker(input: Record<string, unknown>, slot: string): string {
  const s = (v: unknown): string =>
    typeof v === "string" ? v : typeof v === "number" ? String(v) : "";
  const slots = (input.slots ?? {}) as Record<string, Array<Record<string, unknown>>>;
  const first = (slots[slot] ?? [])[0] ?? {};
  switch (slot) {
    case "media":
      return `alt="${s(first.alt)}"`;
    case "title":
      return s(first.text);
    case "body": {
      const content = Array.isArray(first.content) ? first.content : [];
      return content.map((n) => s((n as Record<string, unknown>).value)).join("");
    }
    case "action":
      return s(first.label);
    default:
      return "";
  }
}

test("web card RENDER realizes the MODEL-B projection (ordered slots · tone tint · image · action)", () => {
  const input = loadFixture("card").input;
  const html = renderHtml(input);
  const exp = loadFixture("card").expected as CardProjection;

  // The projection's PRESENT slots realize IN ORDER in the rendered DOM — a
  // dropped or reordered slot in the @barkpark/react card emitter (projector
  // untouched) reds this ordered-spine check (the load-bearing non-vacuous proof).
  assert.deepEqual(
    exp.slots,
    ["media", "title", "body", "action"],
    "projection floor: card must exercise all four model-B slots",
  );
  let prev = -1;
  for (const slot of exp.slots) {
    const marker = cardSlotMarker(input, slot);
    const idx = html.indexOf(marker);
    assert.ok(idx >= 0, `card slot ${slot}: rendered DOM is missing ${JSON.stringify(marker)}`);
    assert.ok(idx > prev, `card slot ${slot} rendered out of model-B order (idx ${idx} <= ${prev})`);
    prev = idx;
  }

  // tone rides the canonical `bp-card--<tone>` class; media fast-path renders <img>.
  if (exp.tone) present(html, `bp-card--${exp.tone}`, `card tone class ${exp.tone}`);
  if (exp.media_fastpath) present(html, "<img", "card media image fast-path");
});

test("web pipeline RENDER realizes every node (kind · title · detail · source_role)", () => {
  const input = loadFixture("pipeline").input;
  const html = renderHtml(input);
  const exp = loadFixture("pipeline").expected as PipelineProjection;
  const roles = exp.nodes.map((n) => n.source_role);
  // non-vacuous: the fixture must exercise BOTH coercion branches.
  assert.ok(roles.includes("origin"), "fixture lost its source:true (origin) node");
  assert.ok(
    roles.includes("provenance"),
    'fixture lost its source:"text" (provenance) node',
  );
  for (const n of exp.nodes) {
    present(html, `>${n.kind}</div>`, `pipeline kind ${n.kind}`);
    present(html, `>${n.title}</div>`, `pipeline title ${n.title}`);
    present(html, `>${n.detail}</div>`, `pipeline detail ${n.detail}`);
    // source_role realizes: origin → the `bp-pnode--src` accent; provenance → the
    // `bp-pnode__src` text line.
    if (n.source_role === "origin") {
      present(html, "bp-pnode--src", "pipeline origin accent");
    } else if (n.source_role === "provenance") {
      present(html, `>${n.source_text}</div>`, `pipeline provenance ${n.source_text}`);
    }
  }
});

