test("web columns RENDER nests each column's children (count + content)", () => {
  const input = loadFixture("columns").input;
  const html = renderHtml(input);
  const exp = loadFixture("columns").expected as ColumnsProjection;
  // Column count is expressed via the `--bp-cols` custom prop — a flatten/mis-nest reds.
  present(html, `--bp-cols:${exp.columns.length}`, "columns grid count");
  const cols = Array.isArray(input.columns) ? (input.columns as unknown[][]) : [];
  exp.columns.forEach((children, ci) => {
    children.forEach((_type, cj) => {
      const text = leafText(cols[ci]?.[cj]);
      if (text) present(html, text, `columns[${ci}] child ${cj}`);
    });
  });
});

test("web section RENDER realizes the grid + nests authored cells in order", () => {
  const input = loadFixture("section").input;
  const html = renderHtml(input);
  const exp = loadFixture("section").expected as SectionProjection;

  present(html, 'class="bp-section__grid"', "section grid");
  // The `repeat()` grid-template ships in paper-surface.css (not the DOM); the
  // canonical renderer emits only the `--bp-tracks` custom prop the rule reads.
  present(html, `--bp-tracks:${exp.tracks}`, "section track count");

  const authored = Array.isArray(input.blocks)
    ? (input.blocks as Array<{ slots?: { title?: unknown[] } }>)
    : [];
  const renderedCells = html.split('<div class="bp-section__cell"').slice(1);
  assert.equal(renderedCells.length, exp.cells.length, "section cell count");

  exp.cells.forEach((cell, i) => {
    const segment = renderedCells[i] ?? "";
    const title = (authored[i]?.slots?.title ?? []).map(leafText).join("");
    assert.ok(title, `section authored cell ${i} has no title text`);
    present(segment, title, `section cell ${i} authored content`);

    if (cell.span == null) {
      assert.doesNotMatch(segment, /grid-column:span /, `section cell ${i} span`);
    } else {
      present(segment, `grid-column:span ${cell.span}`, `section cell ${i} span`);
    }

    if (cell.order == null) {
      assert.doesNotMatch(segment, /order:-?\d+/, `section cell ${i} order`);
    } else {
      present(segment, `order:${cell.order}`, `section cell ${i} order`);
    }
  });
});

test("web terminal RENDER realizes chrome (title · live · footer) + nests children", () => {
  const input = loadFixture("terminal").input;
  const html = renderHtml(input);
  const exp = loadFixture("terminal").expected as TerminalProjection;
  present(html, `>${exp.title}</span>`, "terminal title");
  present(html, exp.footer, "terminal footer");
  if (exp.live) present(html, ">live</span>", "terminal live badge");
  const kids = Array.isArray(input.children)
    ? (input.children as unknown[])
    : Array.isArray(input.blocks)
      ? (input.blocks as unknown[])
      : [];
  exp.children.forEach((_type, ci) => {
    const text = leafText(kids[ci]);
    if (text) present(html, text, `terminal child ${ci}`);
  });
});

test("web task-board RENDER realizes every projection column (role order · label · count · ordered card titles · manifest glyph)", () => {
  const html = renderHtml(fixture.input as Record<string, unknown>);
  // Cross-fixture glyph-char source: the status-legend golden carries the
  // manifest glyph per role. The canonical render derives BOTH surfaces from
  // one ladder — this asserts that derivation instead of a web hand copy
  // (the deleted `task-board-columns.ts` model was that hand copy).
  const legend = loadFixture("status-legend").expected as LegendProjection;
  const legendByRole = new Map(legend.rows.map((r) => [r.role, r]));

  // One rendered column per projection column, in projection order. The golden
  // input populates EXACTLY the projected columns (empty columns collapse), so
  // an extra, dropped, or reordered rendered column reds here.
  const segments = html.split('<div class="bp-board__col ').slice(1);
  assert.equal(
    segments.length,
    fixture.expected.columns.length,
    "rendered board column count",
  );

  fixture.expected.columns.forEach((col, i) => {
    const seg = segments[i] ?? "";
    assert.ok(
      seg.startsWith(`bp-board__col--${col.role}`),
      `column ${i} must be ${col.role} (white-ladder order parity)`,
    );
    present(
      seg,
      `<span class="bp-board__label">${col.label}</span>`,
      `board label ${col.role}`,
    );
    present(
      seg,
      `<span class="bp-board__count">${col.count}</span>`,
      `board count ${col.role}`,
    );

    // Ordered card titles — presence AND order within the column segment.
    let prev = -1;
    for (const card of col.cards) {
      const marker = `<span class="bp-bcard__t">${card.title}</span>`;
      const idx = seg.indexOf(marker);
      assert.ok(
        idx >= 0,
        `board card ${JSON.stringify(card.title)} missing from ${col.role}`,
      );
      assert.ok(
        idx > prev,
        `board card ${JSON.stringify(card.title)} out of order in ${col.role}`,
      );
      prev = idx;
    }

    // The glyph-role realizes at the MANIFEST glyph char. Spinner roles emit
    // the empty CSS-animated span (aria-labelled), never a literal char.
    const lrow = legendByRole.get(col.glyph_role);
    assert.ok(lrow, `legend fixture has no row for glyph role ${col.glyph_role}`);
    if (lrow!.spinner) {
      present(
        seg,
        `<span class="bp-g bp-g--${col.glyph_role}" aria-label=`,
        `board spinner glyph ${col.glyph_role}`,
      );
    } else {
      present(
        seg,
        `<span class="bp-g bp-g--${col.glyph_role}">${lrow!.glyph}</span>`,
        `board glyph ${col.glyph_role}`,
      );
    }
  });
});
